// Demo 1: inserting the number 25 into the sorted array [10, 20, 30, 50, 60]
let arr = [10, 20, 30, 50, 60];
let insertVal = 25;
let shiftCount = 0;

// Simulate physically shifting memory: move elements from the back forward
arr.push(undefined);
for (let i = arr.length - 1; i > 2; i--) {
  arr[i] = arr[i - 1];
  shiftCount++;
}
arr[2] = insertVal;

console.log("Array after insert:", arr);
console.log("Number of memory blocks forced to shift:", shiftCount, "time(s)");
console.log("------------------------------------------");

// Demo 2: a hash function computing a memory index directly (O(1) addressing)
function simpleHash(key, capacity = 10) {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) % capacity;
  }
  return hash;
}

console.log("Slot directly computed for key 'Alice':", simpleHash('Alice'));
console.log("Slot directly computed for key 'Bob':  ", simpleHash('Bob'));
